// fixture returns a tone generated by make fixtures, skipping without it.
func fixture(t *testing.T, name string) string {
	t.Helper()
	path := filepath.Join("testdata", name)
	if _, err := os.Stat(path); err != nil {
		t.Skipf("%s is missing; run make fixtures", path)
	}
	return path
}

func open(t *testing.T, name string) audio.Source {
	t.Helper()
	src, err := Open(fixture(t, name))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { src.Close() })
	return src
}

func readAll(t *testing.T, src audio.Source) []float32 {
	t.Helper()
	var pcm []float32
	buf := make([]float32, 2*1000)
	for {
		n, err := src.Read(buf)
		pcm = append(pcm, buf[:2*n]...)
		if errors.Is(err, io.EOF) {
			return pcm
		}
		if err != nil {
			t.Fatal(err)
		}
	}
}

func TestFLACDecodesExactly(t *testing.T) {
	src := open(t, "tone-48000.flac")
	if src.SampleRate() != 48000 || src.Frames() != 48000 {
		t.Fatalf("rate %d, frames %d; want 48000, 48000", src.SampleRate(), src.Frames())
	}
	pcm := readAll(t, src)
	if len(pcm) != 2*48000 {
		t.Fatalf("decoded %d frames, want 48000", len(pcm)/2)
	}
	var peak float32
	for i := 0; i < len(pcm); i += 2 {
		if pcm[i] != pcm[i+1] {
			t.Fatalf("frame %d: left %v, right %v; the tone is the same on both sides", i/2, pcm[i], pcm[i+1])
		}
		peak = max(peak, pcm[i])
	}
	if peak < 0.05 || peak > 1 {
		t.Fatalf("peak %v; want a sine of plausible amplitude", peak)
	}
}

func TestMP3LengthAndRate(t *testing.T) {
	src := open(t, "tone-44100.mp3")
	if src.SampleRate() != 44100 {
		t.Fatalf("rate %d, want 44100", src.SampleRate())
	}
	// Encoder delay and padding add up to two MP3 frames until gapless
	// trimming arrives.
	if d := src.Frames() - 44100; d < 0 || d > 2*1152 {
		t.Fatalf("frames %d, want 44100 plus at most 2304", src.Frames())
	}
	if pcm := readAll(t, src); int64(len(pcm)/2) != src.Frames() {
		t.Fatalf("decoded %d frames, Frames() said %d", len(pcm)/2, src.Frames())
	}
}

// Without a Xing or Info header an MP3's length is estimated from its bitrate
// rather than counted by decoding the whole file, and reads still run to the
// real end, whichever side of it the estimate falls.
func TestMP3WithoutAHeader(t *testing.T) {
	for _, name := range []string{"noxing-44100.mp3", "noise-untagged.mp3"} {
		src := open(t, name)
		est := src.Frames()
		if n := int64(len(readAll(t, src)) / 2); est < n-1152 || est > n+1152 {
			t.Errorf("%s: Frames() = %d, decoded %d; at a constant bitrate the estimate is within a frame", name, est, n)
		}
	}

	// Cut out of a VBR file, the estimate runs long.
	src := open(t, "noise-cut.mp3")
	if est, n := src.Frames(), int64(len(readAll(t, src))/2); est <= n {
		t.Errorf("noise-cut.mp3: Frames() = %d, decoded %d; want the estimate long", est, n)
	}

	// After a stretch at 320 kbps, 45 s at 128 kbps: the estimate falls well
	// short, and reads and seeks go past it.
	high, err := os.ReadFile(fixture(t, "noise-320k.mp3"))
	if err != nil {
		t.Fatal(err)
	}
	low, err := os.ReadFile(fixture(t, "noise-untagged.mp3"))
	if err != nil {
		t.Fatal(err)
	}
	at := id3Size(high)
	info := high[at:] // LAME's Info frame: MPEG 1 Layer III, 320 kbps at 44.1 kHz
	if string(info[36:40]) != "Info" {
		t.Fatalf("noise-320k.mp3 has no Info frame at %d", at)
	}
	path := filepath.Join(t.TempDir(), "joined.mp3")
	if err := os.WriteFile(path, slices.Concat(info[144*320000/44100+int(info[2]>>1&1):], low), 0o644); err != nil {
		t.Fatal(err)
	}
	if src, err = Open(path); err != nil {
		t.Fatal(err)
	}
	defer src.Close()
	est := src.Frames()
	whole := readAll(t, src)
	if n := int64(len(whole) / 2); est <= 0 || est > n-20*44100 {
		t.Fatalf("Frames() = %d, decoded %d; want an estimate at least 20 s short", est, n)
	}
	frame := est + 10*44100
	if err := src.SeekFrame(frame); err != nil {
		t.Fatal(err)
	}
	same(t, src, whole[2*frame:2*frame+2*5000], false, fmt.Sprintf("after seeking past the estimate to %d", frame))
}

func TestMonoIsCopiedToBothSides(t *testing.T) {
	pcm := readAll(t, open(t, "mono-44100.flac"))
	if len(pcm) != 2*44100 {
		t.Fatalf("decoded %d frames, want 44100", len(pcm)/2)
	}
	var peak float32
	for i := 0; i < len(pcm); i += 2 {
		if pcm[i] != pcm[i+1] {
			t.Fatalf("frame %d differs between sides", i/2)
		}
		peak = max(peak, pcm[i])
	}
	if peak < 0.05 {
		t.Fatalf("peak %v; the mono tone is silent", peak)
	}
}

// crossings counts sign changes of one side of interleaved stereo pcm.
func crossings(pcm []float32, side int) int {
	n := 0
	for i := side + 2; i < len(pcm); i += 2 {
		if (pcm[i-2] < 0) != (pcm[i] < 0) {
			n++
		}
	}
	return n
}

func TestChannelsStaySeparate(t *testing.T) {
	// A sine of f Hz crosses zero 2f times a second: 880 left, 1760 right.
	for _, name := range []string{"stereo-440-880.flac"} {
		t.Run(name, func(t *testing.T) {
			pcm := readAll(t, open(t, name))
			if len(pcm) != 2*44100 {
				t.Fatalf("decoded %d frames, want 44100", len(pcm)/2)
			}
			for side, want := range []int{880, 1760} {
				got := crossings(pcm, side)
				if d := got - want; d < -want/50 || d > want/50 {
					t.Errorf("side %d: %d zero crossings, want %d within 2%%", side, got, want)
				}
			}
		})
	}
}

func TestClosedSourceIsInert(t *testing.T) {
	src, err := Open(fixture(t, "tone-48000.flac"))
	if err != nil {
		t.Fatal(err)
	}
	if err := src.Close(); err != nil {
		t.Fatal(err)
	}
	if n, err := src.Read(make([]float32, 8)); n != 0 || !errors.Is(err, io.EOF) {
		t.Errorf("Read after Close = %d, %v; want 0, io.EOF", n, err)
	}
	if err := src.SeekFrame(0); err == nil {
		t.Error("SeekFrame after Close should fail")
	}
	if err := src.Close(); err != nil {
		t.Errorf("second Close: %v", err)
	}
}

func TestSeek(t *testing.T) {
	whole := readAll(t, open(t, "tone-48000.flac"))
	src := open(t, "tone-48000.flac")
	if err := src.SeekFrame(24000); err != nil {
		t.Fatal(err)
	}
	rest := readAll(t, src)
	if len(rest) != 2*24000 {
		t.Fatalf("%d frames after seeking to 24000, want 24000", len(rest)/2)
	}
	if rest[0] != whole[2*24000] {
		t.Fatalf("first frame after seek %v, want %v", rest[0], whole[2*24000])
	}
}

func TestUnsupportedAndMissing(t *testing.T) {
	if _, err := Open("song.ogg"); !errors.Is(err, ErrUnsupported) {
		t.Errorf("Open(song.ogg) = %v, want ErrUnsupported", err)
	}
	if _, err := Open(filepath.Join(t.TempDir(), "gone.flac")); err == nil {
		t.Error("opening a missing file should fail")
	}
	if !Supported("A/B/01 x.MP3") || !Supported("x.flac") || Supported("cover.jpg") {
		t.Error("Supported disagrees with Open")
	}
}

func TestSurroundIsDownmixed(t *testing.T) {
	// Front left 440, front right 880, centre 220: the centre reaches both sides.
	pcm := readAll(t, open(t, "three-440-880-220.flac"))
	var diff, peakL, peakR float32
	for i := 0; i < len(pcm); i += 2 {
		diff = max(diff, abs(pcm[i]-pcm[i+1]))
		peakL, peakR = max(peakL, pcm[i]), max(peakR, pcm[i+1])
	}
	if diff < 0.01 || peakL < 0.05 || peakR < 0.05 {
		t.Fatalf("diff %v, peaks %v %v: want two different, non-silent sides", diff, peakL, peakR)
	}

	// Only the centre carries sound: it comes out equally on both sides.
	pcm = readAll(t, open(t, "centre-only.flac"))
	var peak float32
	for i := 0; i < len(pcm); i += 2 {
		if pcm[i] != pcm[i+1] {
			t.Fatalf("frame %d: centre-only audio differs between sides", i/2)
		}
		peak = max(peak, pcm[i])
	}
	if peak < 0.02 {
		t.Fatalf("centre-only peak %v: the centre was dropped", peak)
	}
}

func TestOpus(t *testing.T) {
	src := open(t, "tone-48000.opus")
	if src.SampleRate() != 48000 || src.Frames() != 48000 {
		t.Fatalf("rate %d, frames %d; want 48000, 48000", src.SampleRate(), src.Frames())
	}
	if pcm := readAll(t, src); len(pcm) != 2*48000 {
		t.Fatalf("decoded %d frames, want 48000", len(pcm)/2)
	}
	if err := src.SeekFrame(24000); err != nil {
		t.Fatal(err)
	}
	if rest := readAll(t, src); len(rest) != 2*24000 {
		t.Fatalf("%d frames after seeking to 24000, want 24000", len(rest)/2)
	}
	if !Supported("x.opus") {
		t.Fatal("Supported should accept .opus")
	}
}

func TestTruncatedFLACReportsAnError(t *testing.T) {
	data, err := os.ReadFile(fixture(t, "tone-48000.flac"))
	if err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(t.TempDir(), "cut.flac")
	if err := os.WriteFile(path, data[:len(data)*6/10], 0o644); err != nil {
		t.Fatal(err)
	}
	src, err := Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer src.Close()
	buf := make([]float32, 2*1000)
	for {
		_, err := src.Read(buf)
		if err == nil {
			continue
		}
		if !errors.Is(err, io.ErrUnexpectedEOF) {
			t.Fatalf("a cut-off FLAC ended with %v, want io.ErrUnexpectedEOF", err)
		}
		return
	}
}

func abs(x float32) float32 { return max(x, -x) }

func TestM4A(t *testing.T) {
	src := open(t, "tone-44100.m4a")
	if src.SampleRate() != 44100 || src.Frames() != 44100 {
		t.Fatalf("rate %d, frames %d; want 44100, 44100", src.SampleRate(), src.Frames())
	}
	whole := readAll(t, src)
	if len(whole) != 2*44100 {
		t.Fatalf("decoded %d frames, want 44100: the priming or padding wasn't trimmed", len(whole)/2)
	}
	// 440 Hz crosses zero 880 times a second.
	if c := crossings(whole, 0); c < 875 || c > 885 {
		t.Fatalf("%d zero crossings, want about 880", c)
	}

	src = open(t, "tone-44100.m4a")
	if err := src.SeekFrame(22050); err != nil {
		t.Fatal(err)
	}
	rest := readAll(t, src)
	if len(rest) != 2*22050 {
		t.Fatalf("%d frames after seeking to 22050, want 22050", len(rest)/2)
	}
	for i := range rest[:2000] {
		if abs(rest[i]-whole[2*22050+i]) > 1e-3 {
			t.Fatalf("sample %d after the seek is %v, want %v", i, rest[i], whole[2*22050+i])
		}
	}
	if !Supported("x.M4A") {
		t.Fatal("Supported should accept .m4a")
	}
}

func TestM4AUpsampledMono(t *testing.T) {
	// faad2 decodes AAC at 24 kHz or less at double rate, in case it carries
	// SBR; the priming and length scale with it.
	src := open(t, "mono-22050.m4a")
	if src.SampleRate() != 44100 || src.Frames() != 44100 {
		t.Fatalf("rate %d, frames %d; want 44100, 44100", src.SampleRate(), src.Frames())
	}
	pcm := readAll(t, src)
	if len(pcm) != 2*44100 {
		t.Fatalf("decoded %d frames, want 44100", len(pcm)/2)
	}
	for i := 0; i < len(pcm); i += 2 {
		if pcm[i] != pcm[i+1] {
			t.Fatalf("frame %d: mono differs between sides", i/2)
		}
	}
	// The SBR filterbank keeps the frame before in its output, which a seek
	// has to run past.
	seekMatches(t, "mono-22050.m4a", pcm, 22050)
}

