// Seeks must land on the same frame a straight decode reaches and leave the
// rest of the file, including the trimmed end, exactly as it was.
func TestMP3SeeksMatchAStraightDecode(t *testing.T) {
	for _, name := range []string{
		"noise-180s.mp3", "noise-320k.mp3", "noise-256k-48000.mp3", "noise-reservoir0.mp3",
		"noise-v0.mp3", "noise-v4.mp3", "noise-60s-22050.mp3", "noise-11025.mp3", "noise-8000.mp3",
		"noise-untagged.mp3", "noise-cut.mp3", "noise-joined.mp3",
	} {
		t.Run(name, func(t *testing.T) {
			whole := readAll(t, open(t, name))
			n := int64(len(whole) / 2)
			src := open(t, name)
			// Far and near, forward and back, to the start and from it, and
			// into the last frames; some read on to the end, some a little.
			for _, step := range []struct {
				at    float64
				toEnd bool
			}{{0.3, false}, {0.31, false}, {0.7, true}, {0.5, false}, {0.2, false}, {0.02, true}, {0, false}, {0.999, true}, {0.6, true}} {
				frame := int64(step.at * float64(n))
				if err := src.SeekFrame(frame); err != nil {
					t.Fatal(err)
				}
				want := whole[2*frame:]
				if !step.toEnd {
					want = want[:min(len(want), 2*5000)]
				}
				same(t, src, want, step.toEnd, fmt.Sprintf("after seeking to frame %d of %d", frame, n))
			}
		})
	}
}

// same reads len(want)/2 frames from src, or all it has left if toEnd, and
// fails where they first differ from want.
func same(t *testing.T, src audio.Source, want []float32, toEnd bool, what string) {
	t.Helper()
	buf := make([]float32, 2*1000)
	i := 0
	for toEnd || i < len(want) {
		b := buf
		if !toEnd {
			b = buf[:min(len(buf), len(want)-i)]
		}
		n, err := src.Read(b)
		for j, v := range b[:2*n] {
			if i+j >= len(want) {
				t.Fatalf("%s: more than the %d frames a straight decode has left", what, len(want)/2)
			}
			if v != want[i+j] {
				t.Fatalf("%s: frame %d is %v, want %v", what, (i+j)/2, v, want[i+j])
			}
		}
		i += 2 * n
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			t.Fatal(err)
		}
	}
	if i != len(want) {
		t.Fatalf("%s: read %d frames, want %d", what, i/2, len(want)/2)
	}
}

func TestMP3FarSeeksAreFast(t *testing.T) {
	const name = "noise-180s.mp3"
	far := int64(170 * 44100)
	straight := open(t, name)
	start := time.Now()
	buf := make([]float32, 2*1152)
	for left := far; left > 0; {
		n, err := straight.Read(buf[:2*min(left, 1152)])
		if err != nil {
			t.Fatal(err)
		}
		left -= int64(n)
	}
	read := time.Since(start)

	src := open(t, name)
	start = time.Now()
	if err := src.SeekFrame(far); err != nil { // walks the frame headers
		t.Fatal(err)
	}
	first := time.Since(start)
	if err := src.SeekFrame(far / 3); err != nil {
		t.Fatal(err)
	}
	start = time.Now()
	if err := src.SeekFrame(far); err != nil {
		t.Fatal(err)
	}
	again := time.Since(start)
	t.Logf("to %d s: decoding %v, first seek %v, seek again %v", far/44100, read, first, again)
	if again*10 > read {
		t.Fatalf("a seek to %d s took %v, decoding there %v", far/44100, again, read)
	}
}
